/**
 * The frontend's presence rule against the backend's own answers.
 *
 * `looksPresent`/`stemWord` exist so the form can block an aspect the API
 * would refuse with 422. That is only safe while the two implementations
 * agree, and nothing in either language can notice a disagreement on its own.
 * So the Python side records its verdicts in a fixture
 * (`backend/tests/fixtures/stem_parity.json`, regenerated by the script
 * beside it) and this file holds TypeScript to them. The backend is the
 * authority: it returns the status code.
 *
 * A failure here is not a flaky test. It means the UI and the API now
 * disagree about whether a request is answerable.
 */

import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'

import { describe, expect, it } from 'vitest'

import { looksPresent, stemWord } from './words'

interface StemCase {
  word: string
  stem: string
}

interface PresenceCase {
  text: string
  aspect: string
  present: boolean
}

interface Fixture {
  stems: StemCase[]
  presence: PresenceCase[]
}

// Resolved from the Vitest root (this package's directory) rather than from
// `import.meta.url`, which is not a file URL once Vite has transformed the
// module. The fixture lives in the backend on purpose: it is the backend's
// rule, and this package only mirrors it.
const FIXTURE_PATH = resolve(process.cwd(), '../backend/tests/fixtures/stem_parity.json')

const fixture: Fixture = JSON.parse(readFileSync(FIXTURE_PATH, 'utf8')) as Fixture

/**
 * Python's `str.casefold()` maps "ß" to "ss"; JavaScript's `toLowerCase()`
 * leaves it alone, and the language offers no casefold. So a word containing
 * the letter itself stems differently on the two sides -- exactly one entry
 * in the fixture. (Upper-case "STRASSE" already agrees: both sides give
 * "strasse", since there is no ß left to fold.)
 *
 * It is listed rather than fixed because the fix is worse than the bug: a
 * hand-rolled casefold table in `words.ts` would be a second, subtler way for
 * the two rules to drift. The consequence is bounded -- a German review using
 * "ß" in an aspect term can be hinted as absent by the UI and still answered
 * by the API, i.e. the UI is stricter than the server, never looser. Both
 * corpora are English.
 *
 * If this ever matters, the right fix is on the Python side: `.lower()`
 * instead of `.casefold()`, which is what JavaScript can actually match.
 */
const KNOWN_CASEFOLD_DIVERGENCE = new Set(['Straße'])

describe('stemWord matches the backend, word for word', () => {
  const shared = fixture.stems.filter((c) => !KNOWN_CASEFOLD_DIVERGENCE.has(c.word))

  it('has a fixture to check against', () => {
    expect(shared.length).toBeGreaterThan(50)
  })

  it.each(shared)('stems $word to $stem, as Python does', ({ word, stem }) => {
    expect(stemWord(word)).toBe(stem)
  })
})

describe('the known casefold divergence', () => {
  it.each([...KNOWN_CASEFOLD_DIVERGENCE])(
    'still differs for %s, and in the stricter direction',
    (word) => {
      const pythonStem = fixture.stems.find((c) => c.word === word)?.stem
      expect(pythonStem).toBeDefined()
      expect(stemWord(word)).not.toBe(pythonStem)
      // The UI must only ever be stricter: it may hint "absent" for something
      // the API would answer, never the other way round.
      expect(looksPresent('die Straße war laut', 'Straße')).toBe(true)
    },
  )
})

describe('looksPresent matches the backend on every recorded pair', () => {
  it('has a fixture to check against', () => {
    expect(fixture.presence.length).toBeGreaterThan(25)
  })

  it.each(fixture.presence)(
    'agrees that $aspect is present=$present',
    ({ text, aspect, present }) => {
      expect(looksPresent(text, aspect)).toBe(present)
    },
  )

  it('never says present where the backend says absent', () => {
    // The asymmetry that matters: a false "present" here means the form sends
    // a request the API refuses with 422, which the user sees as a dead end.
    const looser = fixture.presence.filter(
      (c) => !c.present && looksPresent(c.text, c.aspect),
    )
    expect(looser).toEqual([])
  })
})
